  private Node add(int v, Node n){
    if( n == null ){
      n = new Node();
      n.val = v;
    }
    if( v < n.val )
      n.lc = add(v, n.lc);
    else if( v > n.val )
      n.rc = add( v, n.rc);
    return n;
  }

  public void show(){
    show(myCon);
